// Hand-written `@trpc/react-query` stub for the flowatlas fixture suite.
//
// The real bindings are a proxy whose members are inferred from the router's type,
// so `trpc.orders.list.useQuery(input)` typechecks because the type system walked
// the router. A stub cannot express that and must not pretend to — so it declares
// the *kind* the real thing is, an object whose members are reached by name and
// whose leaves answer the hooks, and says nothing about which names exist.

export interface QueryResult {
  readonly data: unknown;
}

export interface MutationResult {
  mutate(input?: unknown): void;
}

/** A node of the proxy: another node under any name, or a hook at a leaf. */
export interface ReactNode {
  useQuery(input?: unknown): QueryResult;
  useSuspenseQuery(input?: unknown): [unknown, QueryResult];
  useMutation(): MutationResult;
  [name: string]: ReactNode | ((input?: unknown) => unknown);
}

export declare function createTRPCReact<TRouter>(): Record<string, ReactNode>;
